#include "dd.h"
#include "base.cc"
void exercise(const std::string& d,const std::string& mode,bool comp,bool wal,size_t count,const std::string& out){auto oracle=loadOracle(d);auto before=Manifest::Load(d+"/MANIFEST");prewarm(d);auto opts=options(0);opts.enableWal=wal;auto db=std::make_unique<DB>(d,opts);std::vector<WriteBatch> batches;std::vector<std::string> live;for(auto&p:oracle)if(p.second.key.type==ValueType::kValue)live.push_back(p.first);std::vector<size_t> trace(count);std::mt19937_64 rng(20261115);for(auto&i:trace)i=rng()%live.size();bool writing=mode=="write";if(writing){batches.resize(count);for(size_t i=0;i<count;++i)for(size_t j=0;j<64;++j){auto id=i*64+j;auto k=key(1000000+id);auto v=value(id,7);batches[i].Put(k,v);oracle[k]={{k,before.LastSequence()+id+1,ValueType::kValue},v};}}
std::vector<Sample> samples(count);std::vector<std::optional<std::string>> results(writing?0:count);std::atomic<size_t> done{0};std::atomic<bool> go{false};std::exception_ptr error;Clock::time_point begin,end;std::thread worker([&]{try{while(!go.load())std::this_thread::yield();DD_PHASE(3);begin=Clock::now();for(size_t i=0;i<count;++i){auto a=Clock::now();if(writing)db->Write(batches[i]);else results[i]=db->Get(live[trace[i]]);auto b=Clock::now();samples[i]={ns(begin,a),ns(a,b)};done=i+1;}end=Clock::now();}catch(...){error=std::current_exception();done=count;}});
auto totalStart=Clock::now();go=true;while(done.load()<std::min<size_t>(writing?4:512,count))std::this_thread::yield();auto ca=Clock::now();if(comp)db->Compact();auto cb=Clock::now();worker.join();if(error)std::rethrow_exception(error);auto f=Clock::now();{DD_PHASE(4);db->Flush();}auto fe=Clock::now();db.reset();auto closed=Clock::now();auto peak=rss();
// Validation outside timing: full oracle, latest physical sequences/tombstones, MANIFEST and cleanup.
{DD_PHASE(7);DB reopen(d,options(0));verify(reopen,oracle);}if(!writing)for(size_t i=0;i<count;++i)need(results[i]&&*results[i]==oracle.at(live[trace[i]]).value,"read result mismatch");auto after=Manifest::Load(d+"/MANIFEST");need(after.FlushedSequence()==before.FlushedSequence()+(writing?count*64:0),"FlushedSequence mismatch");std::map<std::string,lsm::Entry> actual;size_t physical=0,newTables=0;for(const auto&t:after.Tables()){if(t.minSequence>before.LastSequence())++newTables;SSTableReader r(path(d,t.fileNumber));for(auto it=r.Begin();it.Valid();it.Next()){auto k=it.Key();auto found=actual.find(k.user_key);if(found==actual.end()||found->second.key.sequence<k.sequence)actual[k.user_key]={k,it.Value()};}}need(actual.size()==oracle.size(),"physical keys mismatch");for(const auto&p:oracle){auto q=actual.find(p.first);need(q!=actual.end()&&q->second.key.sequence==p.second.key.sequence&&q->second.key.type==p.second.key.type&&q->second.value==p.second.value,"physical sequence/type mismatch");}for(auto&p:fs::directory_iterator(d))if(p.path().extension()==".sst")++physical;need(physical==after.Tables().size(),"orphan SST after join");if(comp)for(auto&t:before.Tables())need(!fs::exists(path(d,t.fileNumber)),"old input not cleaned");
std::cout<<"{\"mode\":\""<<mode<<"\",\"compaction\":"<<comp<<",\"wal\":"<<wal<<",\"batches\":"<<(writing?count:0)<<",\"logical_ops\":"<<(writing?count*64:count)<<",\"compact_start_ns\":"<<ns(begin,ca)<<",\"compact_end_ns\":"<<ns(begin,cb)<<",\"compact_ns\":"<<(comp?ns(ca,cb):0)<<",\"flush_ns\":"<<ns(f,fe)<<",\"close_ns\":"<<ns(fe,closed)<<",\"total_ns\":"<<ns(totalStart,closed)<<",\"rss_kib\":"<<peak<<",\"tables_after\":"<<after.Tables().size()<<",\"new_only_tables\":"<<newTables<<",\"flushed_sequence\":"<<after.FlushedSequence()<<",\"requests\":";emitLatency("api",samples,ns(begin,end),out+"-timeline.csv");std::cout<<",\"verified\":true}\n";}
int main(int argc,char**argv){std::cout<<std::setprecision(17);try{std::string mode=argv[1];if(mode=="compact")compact(argv[2],true,4194304);else exercise(argv[2],mode,std::stoi(argv[3]),std::stoi(argv[4]),std::stoull(argv[5]),argv[6]);
#ifdef PROBE
if(auto*f=std::getenv("DD_OUT"))dd::dump(f);
#endif
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
